<template>
  <section class="container py-4 meeting-workspace">
    <header class="workspace-heading"><div><p class="eyebrow">{{ auth.user?.church?.name }}</p><div class="creation-heading"><h1>{{ tr('Juntas', 'Meetings') }}</h1><button v-write="'meetings'" v-if="manager" type="button" class="creation-plus" :aria-label="tr('Abrir junta', 'Open meeting')" :title="tr('Abrir junta', 'Open meeting')" @click="newMeeting = true"><span aria-hidden="true">+</span></button></div><p>{{ manager ? tr('Prepara la agenda, dirige la junta y publica sus acuerdos.', 'Prepare the agenda, run the meeting and publish its decisions.') : tr('Presenta puntos y consulta la agenda, tus acuerdos y las actas públicas.', 'Submit points and view agendas, your decisions and public minutes.') }}</p></div></header>
    <p v-if="error" role="alert" class="notice error">{{ error }}</p>
    <nav class="workspace-tabs"><button :class="{selected: tab === 'meeting'}" @click="tab = 'meeting'">{{ tr('Junta y agenda', 'Meeting and agenda') }}</button><button :class="{selected: tab === 'report'}" @click="tab = 'report'">{{ tr('Historial de puntos', 'Point history') }}</button><button :class="{selected: tab === 'archive'}" @click="tab = 'archive'">{{ tr('Actas anteriores', 'Previous minutes') }}</button></nav>
    <p v-if="loading" class="surface empty" role="status">{{ tr('Cargando…', 'Loading…') }}</p>
    <template v-if="!loading && tab === 'meeting'">
      <div class="surface toolbar"><label>{{ tr('Seleccionar junta', 'Select meeting') }}<select v-model="selectedId" class="form-select" @change="selectMeeting"><option value="">{{ tr('Seleccionar', 'Select') }}</option><option v-for="m in meetings" :key="m.id" :value="String(m.id)">{{ date(m.planned_start_at) }} · {{ state(m) }}</option></select></label><button class="btn btn-outline-secondary" :disabled="busy" @click="refresh">{{ tr('Actualizar', 'Refresh') }}</button></div>
      <div v-if="!meeting" class="surface empty">{{ tr('Selecciona una junta o espera a que Secretaría abra la próxima.', 'Select a meeting or wait for the clerk to open the next one.') }}</div>
      <template v-else>
        <div class="summary-grid"><article><span>{{ tr('Estado', 'Status') }}</span><strong>{{ state(meeting) }}</strong></article><article><span>{{ tr('Cierre de agenda', 'Agenda deadline') }}</span><strong>{{ date(meeting.submission_deadline) }}</strong></article><article><span>{{ tr('Lugar', 'Location') }}</span><strong>{{ meeting.location || '—' }}</strong></article></div>
        <p v-if="meeting.start_at" class="muted">{{ tr('Inicio real', 'Actual start') }}: {{ date(meeting.start_at) }}<span v-if="meeting.end_at"> · {{ tr('Fin real', 'Actual end') }}: {{ date(meeting.end_at) }}</span></p>
        <div class="notice">{{ accepting ? tr('Las solicitudes y su revisión cierran 24 horas antes de la junta.', 'Submissions and reviews close 24 hours before the meeting.') : tr('Agenda cerrada. Solo los puntos aceptados forman parte de la junta.', 'Agenda closed. Only accepted points are included in the meeting.') }}</div>
        <div class="toolbar"><button v-write="'meetings'" v-if="manager && !meeting.start_at && !meeting.end_at" class="btn btn-outline-success" :disabled="busy || now < new Date(meeting.planned_start_at).getTime()" @click="run(() => meetingApi.startMeeting(meeting.id))">{{ tr('Iniciar junta en vivo', 'Start live meeting') }}</button><button v-if="manager && live" class="btn btn-outline-danger" :disabled="busy || undecided > 0" @click="finishConfirm = true">{{ tr('Finalizar junta', 'Finish meeting') }}</button><span v-if="manager && live" class="muted">{{ undecided }} {{ tr('puntos pendientes de decisión', 'points awaiting a decision') }}</span></div>
        <details v-if="manager && live" :key="meeting.id" class="surface previous-minutes">
          <summary>{{ tr('Leer acta de la junta anterior','Read previous meeting minutes') }}<span v-if="previousMeeting"> · #{{ previousMeeting.minutes_number }} · {{ date(previousMeeting.planned_start_at) }}</span></summary>
          <template v-if="previousMeeting"><p class="muted">{{ previousMeeting.summary_public ? tr('Acta pública','Public minutes') : tr('Acta privada · Solo visible para quien dirige la junta','Private minutes · Only visible to the meeting manager') }}</p><MeetingOverview :meeting="previousMeeting" :locale="ui.locale" /><button class="btn btn-outline-secondary" @click="downloadSummary(previousMeeting)">{{ tr('Descargar PDF','Download PDF') }}</button></template>
          <p v-else class="empty">{{ tr('No hay una junta anterior finalizada en esta iglesia.','No previous completed meeting exists in this church.') }}</p>
        </details>
        <section v-if="manager && !meeting.end_at" class="surface">
          <h2>{{ tr('Apertura y asistencia', 'Opening and attendance') }}</h2>
          <form v-write="'meetings'" @submit.prevent="saveOpening"><!-- Read-only users can still inspect attendance. --><fieldset :disabled="busy || !(auth.canEdit('meetings') || auth.canEdit('meeting_points'))"><div class="form-grid"><label>{{ tr('Oración inicial (persona)', 'Opening prayer (person)') }}<input v-model="opening.prayer" class="form-control" /></label><label>{{ tr('Observaciones iniciales', 'Opening remarks') }}<textarea v-model="opening.remarks" class="form-control" rows="2"></textarea></label></div>
          <div class="attendance-list"><div v-for="(person, index) in attendance" :key="index" class="attendance-row"><input v-model="person.name" class="form-control" :aria-label="tr('Participante', 'Participant')" required /><select v-model="person.status" class="form-select" :aria-label="tr('Asistencia', 'Attendance')"><option value="present">{{ tr('Presente', 'Present') }}</option><option value="absent">{{ tr('Ausente', 'Absent') }}</option><option value="online">{{ tr('En línea', 'Online') }}</option></select><button v-write="'meetings'" type="button" class="btn btn-outline-secondary" :aria-label="tr('Quitar participante', 'Remove participant')" @click="attendance.splice(index, 1)">×</button></div></div>
          <div class="toolbar"><button v-write="'meetings'" type="button" class="btn btn-outline-secondary" @click="attendance.push({name:'',status:'present'})">+ {{ tr('Participante', 'Participant') }}</button><button class="btn btn-primary">{{ tr('Guardar apertura y asistencia', 'Save opening and attendance') }}</button></div></fieldset></form>
        </section>
        <section class="surface">
          <div class="section-heading"><div class="creation-heading"><h2>{{ manager ? tr('Solicitudes y agenda', 'Requests and agenda') : tr('Agenda compartida', 'Shared agenda') }}</h2><button v-if="canSubmit && accepting" type="button" class="creation-plus" :aria-label="tr('Nuevo punto', 'New point')" :title="tr('Nuevo punto', 'New point')" @click="openPoint()"><span aria-hidden="true">+</span></button></div><div v-if="manager" class="toolbar"><select v-model="departmentFilter" class="form-select" :aria-label="tr('Departamento', 'Department')"><option value="">{{ tr('Todos los departamentos', 'All departments') }}</option><option v-for="d in departments" :key="d.id" :value="String(d.id)">{{ d.name }}</option><option value="clerk">{{ tr('Secretaría', 'Clerk') }}</option></select><select v-model="statusFilter" class="form-select" :aria-label="tr('Estado', 'Status')"><option value="">{{ tr('Todos los estados', 'All statuses') }}</option><option v-for="s in reviewStatuses" :key="s" :value="s">{{ label(s) }}</option></select></div></div>
          <p v-if="!displayedAgenda.length" class="empty">{{ tr('No hay puntos disponibles. La agenda se comparte al cierre.', 'No points available. The agenda is shared at the deadline.') }}</p>
          <article v-for="p in displayedAgenda" :key="p.id" class="point-row" :class="{active: manager && meeting.active_meeting_point_id === p.id}">
            <div class="point-heading"><div><span class="department-label" :style="{borderColor:p.department?.color || '#719383'}">{{ p.department?.name || tr('Secretaría', 'Clerk') }}</span><h3>{{ p.agenda_order }}. {{ p.title }}</h3></div><span class="status-pill">{{ label(p.final_status || p.status) }}</span></div><p class="prewrap">{{ p.description }}</p><p v-if="p.review_note" class="muted prewrap">{{ tr('Revisión', 'Review') }}: {{ p.review_note }}</p><p v-for="note in p.notes" :key="note.id" class="muted prewrap">{{ note.note }}</p><p v-if="p.final_note" class="notice prewrap">{{ tr('Acuerdo', 'Decision') }}: {{ p.final_note }}</p>
            <MeetingCalendarReview v-if="manager && auth.canEdit('meetings') && auth.canEdit('calendar') && live && p.calendar_review && !p.final_status && meeting.active_meeting_point_id === p.id" :key="p.id" :point="p" :locale="ui.locale" @reviewed="refresh(true)" /><div class="toolbar"><button v-write="'meetings'" v-if="manager && accepting" class="btn btn-outline-secondary" @click="reviewPoint(p)">{{ tr('Revisar', 'Review') }}</button><button v-write="'meetings'" v-if="manager && accepting" class="btn btn-outline-secondary" @click="move(p,-1)">↑</button><button v-write="'meetings'" v-if="manager && accepting" class="btn btn-outline-secondary" @click="move(p,1)">↓</button><button v-write="'meetings'" v-if="manager && live && p.status === 'accepted' && !p.final_status && meeting.active_meeting_point_id !== p.id" :disabled="busy || !!meeting.active_meeting_point_id" class="btn btn-outline-success" @click="run(() => meetingApi.activateMeetingPoint(p.id))">{{ tr('Discutir punto', 'Discuss point') }}</button><button v-write="'meetings'" v-if="manager && live && meeting.active_meeting_point_id === p.id" class="btn btn-primary" @click="decidePoint(p)">{{ tr('Registrar decisión', 'Record decision') }}</button><button v-write="'meetings'" v-if="manager && live && p.status === 'accepted' && !p.final_status" class="btn btn-outline-secondary" :disabled="busy" @click="decisionForm = {id:p.id,title:p.title,final_status:'postponed',final_note:''}">{{ tr('Diferir a próxima junta', 'Defer to next meeting') }}</button><button v-if="p.history?.length" class="btn btn-outline-secondary" @click="historyPoint = p">{{ tr('Historial', 'History') }}</button></div>
          </article>
        </section>
        <section v-if="!manager" class="surface"><h2>{{ tr('Mis puntos', 'My points') }}</h2><p v-if="!points.length" class="empty">{{ tr('No has presentado puntos para esta junta.', 'No points submitted for this meeting.') }}</p><article v-for="p in points" :key="p.id" class="point-row"><div class="point-heading"><h3>{{ p.title }}</h3><span class="status-pill">{{ label(p.final_status || p.status) }}</span></div><p class="prewrap">{{ p.description }}</p><p v-if="p.review_note || p.final_note" class="notice prewrap">{{ p.final_note || p.review_note }}</p><div class="toolbar"><button v-if="canSubmit && accepting && p.status === 'needs_update'" class="btn btn-primary" @click="openPoint(p)">{{ tr('Actualizar y reenviar', 'Update and resubmit') }}</button><button v-if="p.history?.length" class="btn btn-outline-secondary" @click="historyPoint=p">{{ tr('Historial', 'History') }}</button></div></article></section>
        <section v-if="manager && live" class="surface"><h2>{{ tr('Notas de la junta', 'Meeting notes') }}</h2><p v-for="note in meeting.meeting_notes" :key="note.id" class="prewrap">{{ note.note }}</p><form v-write="'meetings'" @submit.prevent="saveNote"><label>{{ tr('Nueva nota', 'New note') }}<textarea v-model="generalNote" class="form-control" required></textarea></label><button :disabled="busy" class="btn btn-outline-secondary mt-2">{{ tr('Guardar nota', 'Save note') }}</button></form></section>
        <section v-if="meeting.end_at" class="surface"><h2>{{ tr('Acta de la junta', 'Meeting minutes') }}</h2><MeetingOverview v-if="manager || meeting.summary_public" :meeting="meeting" :locale="ui.locale" /><template v-if="manager"><p class="muted">{{ tr('El acta incluye únicamente los resultados de votación; las notas de trabajo permanecen en el historial.','Minutes include only vote outcomes; working notes remain in history.') }}</p><label class="check-label"><input v-model="summary.public" type="checkbox" />{{ tr('Pública: disponible para todos los departamentos', 'Public: available to every department') }}</label><button class="btn btn-primary" :disabled="busy" @click="saveSummary">{{ tr('Guardar acta', 'Save minutes') }}</button></template><p v-else-if="!meeting.summary_public" class="prewrap">{{ tr('Acta privada. Puedes consultar las decisiones de tus puntos.', 'Private minutes. You can view decisions on your own points.') }}</p><button v-if="manager || meeting.summary_public" class="btn btn-outline-secondary ms-2" @click="downloadSummary(meeting)">{{ tr('Descargar PDF', 'Download PDF') }}</button></section>
      </template>
      <section v-if="waitingPoints.length" class="surface"><h2>{{ tr('Pendientes para la próxima junta', 'Waiting for the next meeting') }}</h2><p class="muted">{{ tr('Los puntos se vinculan y envían una sola vez al abrir la próxima junta.', 'Points are linked and submitted once when the next meeting opens.') }}</p><article v-for="p in waitingPoints" :key="p.id" class="point-row"><h3>{{ p.title }}</h3><p>{{ label(p.final_status) }} · {{ date(p.meeting.planned_start_at) }}</p><p v-if="p.final_note">{{ p.final_note }}</p><p v-if="p.revision" class="notice">{{ tr('Revisión lista para la próxima junta.', 'Revision ready for the next meeting.') }}</p><button v-if="canSubmit && (!manager || !p.department_id) && p.final_status === 'needs_update'" class="btn btn-outline-primary" @click="openPoint(p)">{{ tr('Actualizar solicitud', 'Update request') }}</button></article></section>
    </template>
    <section v-if="!loading && tab === 'archive'" class="surface"><h2>{{ manager ? tr('Actas de juntas cerradas', 'Closed meeting minutes') : tr('Actas de juntas', 'Meeting minutes') }}</h2><p v-if="!archive.length" class="empty">{{ tr('No hay actas disponibles.', 'No minutes available.') }}</p><article v-for="m in archive" :key="m.id" class="point-row"><div class="point-heading"><h3>#{{ m.minutes_number }} · {{ date(m.planned_start_at) }} · {{ m.location || '—' }}</h3><span>{{ m.summary_public ? tr('Pública','Public') : tr('Privada','Private') }}</span></div><template v-if="manager || m.summary_public"><MeetingOverview :meeting="m" :locale="ui.locale" /></template><p v-else class="notice">{{ tr('Acta de junta privada', 'Meeting overview private') }}</p><button v-if="manager || m.summary_public" class="btn btn-outline-secondary" @click="downloadSummary(m)">{{ tr('Descargar PDF', 'Download PDF') }}</button></article></section>
    <section v-if="!loading && tab === 'report'" class="surface"><div class="section-heading"><h2>{{ tr('Puntos de todas las juntas', 'Points across all meetings') }}</h2><div class="toolbar"><button class="btn btn-outline-secondary" :disabled="!filteredReport.length" @click="exportReport('csv')">CSV</button><button class="btn btn-outline-secondary" :disabled="!filteredReport.length" @click="exportReport('pdf')">PDF</button></div></div><label><span class="visually-hidden">{{ tr('Buscar', 'Search') }}</span><input v-model="reportSearch" class="form-control" type="search" :placeholder="tr('Buscar', 'Search')" /></label><div class="table-responsive mt-3"><table class="table" data-dt="off"><thead><tr><th>{{ tr('Junta', 'Meeting') }}</th><th>{{ tr('Departamento', 'Department') }}</th><th>{{ tr('Punto', 'Point') }}</th><th>{{ tr('Revisión', 'Review') }}</th><th>{{ tr('Decisión', 'Decision') }}</th><th>{{ tr('Acuerdo', 'Decision note') }}</th><th>{{ tr('Origen', 'Source') }}</th></tr></thead><tbody><tr v-for="p in filteredReport" :key="p.id"><td>{{ date(p.meeting.planned_start_at) }}</td><td>{{ p.department?.name || tr('Secretaría','Clerk') }}</td><td>#{{ p.id }} · {{ p.title }}</td><td>{{ label(p.status) }}</td><td>{{ p.final_status ? label(p.final_status) : '—' }}</td><td>{{ p.final_note || p.review_note || '—' }}</td><td>{{ p.related_meeting_point_id ? '#'+p.related_meeting_point_id : '—' }}</td></tr></tbody></table></div></section>
    <div v-if="newMeeting || pointForm || reviewForm || decisionForm || historyPoint || finishConfirm" class="modal-backdrop" @click.self="closeModal">
      <section class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="meeting-dialog-title"><header class="modal-header"><h2 id="meeting-dialog-title">{{ modalTitle }}</h2><button class="modal-close" :disabled="busy" @click="closeModal" :aria-label="tr('Cerrar','Close')">×</button></header>
      <p v-if="modalError" class="notice error" role="alert">{{ modalError }}</p>
      <form v-write="'meetings'" v-if="newMeeting" @submit.prevent="createMeeting"><fieldset :disabled="busy || !(auth.canEdit('meetings') || auth.canEdit('meeting_points'))"><label v-if="auth.user?.role === 'superadmin'">{{ tr('Iglesia','Church') }}<select v-model="create.church_id" class="form-select" required><option value="">{{ tr('Seleccionar','Select') }}</option><option v-for="c in churches" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label>{{ tr('Fecha y hora','Date and time') }}<input v-model="create.start" class="form-control" type="datetime-local" required /></label><label>{{ tr('Lugar','Location') }}<input v-model="create.location" class="form-control" /></label><button class="btn btn-primary">{{ tr('Abrir junta','Open meeting') }}</button></fieldset></form>
      <form v-if="pointForm" @submit.prevent="submitPoint"><fieldset :disabled="busy || !(auth.canEdit('meetings') || auth.canEdit('meeting_points'))"><label>{{ tr('Título','Title') }}<input v-model="pointForm.title" class="form-control" maxlength="255" required /></label><label>{{ tr('Solicitud y motivo','Request and reason') }}<textarea v-model="pointForm.description" class="form-control" rows="5" required></textarea></label><template v-if="manager && !pointForm.id"><label class="check-label"><input v-model="pointForm.calendar_review" type="checkbox" />{{ tr('Revisar eventos del calendario','Review calendar events') }}</label><div v-if="pointForm.calendar_review" class="form-grid"><label>{{ tr('Desde','From') }}<input v-model="pointForm.calendar_from" class="form-control" type="date" required /></label><label>{{ tr('Hasta','Through') }}<input v-model="pointForm.calendar_until" class="form-control" type="date" :min="pointForm.calendar_from" required /></label></div></template><button class="btn btn-primary">{{ pointForm.id ? tr('Reenviar','Resubmit') : tr('Presentar punto','Submit point') }}</button></fieldset></form>
      <form v-write="'meetings'" v-if="reviewForm" @submit.prevent="submitReview"><fieldset :disabled="busy || !(auth.canEdit('meetings') || auth.canEdit('meeting_points'))"><p>{{ reviewForm.title }}</p><label>{{ tr('Revisión','Review') }}<select v-model="reviewForm.status" class="form-select"><option v-for="s in ['accepted','rejected','needs_update']" :key="s" :value="s">{{ label(s) }}</option></select></label><label>{{ tr('Nota para el departamento','Note for the department') }}<textarea v-model="reviewForm.review_note" class="form-control" :required="reviewForm.status === 'needs_update'"></textarea></label><button class="btn btn-primary">{{ tr('Guardar revisión','Save review') }}</button></fieldset></form>
      <form v-write="'meetings'" v-if="decisionForm" @submit.prevent="submitDecision"><fieldset :disabled="busy || !(auth.canEdit('meetings') || auth.canEdit('meeting_points'))"><p>{{ decisionForm.title }}</p><label>{{ tr('Resultado de la votación','Vote outcome') }}<select v-model="decisionForm.final_status" class="form-select"><option v-for="s in ['approved','denied','needs_update','postponed','informative']" :key="s" :value="s">{{ label(s) }}</option></select></label><label>{{ tr('Acuerdo y detalles','Decision and details') }}<textarea v-model="decisionForm.final_note" class="form-control" :required="decisionForm.final_status === 'needs_update'"></textarea></label><button class="btn btn-primary">{{ tr('Registrar decisión','Record decision') }}</button></fieldset></form>
      <template v-if="historyPoint"><h3>{{ historyPoint.title }}</h3><p v-for="(h,i) in historyPoint.history" :key="i" class="history-entry">{{ date(h.at) }} · {{ label(h.action) }} · {{ h.actor_name }}<span v-if="h.note" class="d-block prewrap">{{ h.note }}</span></p></template>
      <template v-if="finishConfirm"><label>{{ tr('Notas de cierre (opcional)', 'Closing notes (optional)') }}<textarea v-model="closingNotes" class="form-control" rows="4" maxlength="20000" :disabled="busy"></textarea></label><p>{{ tr('Se cerrará la junta y se generará un acta privada. Después podrás publicarla para los departamentos.', 'The meeting will close and private minutes will be generated. You can then publish them for departments.') }}</p><button v-write="'meetings'" class="btn btn-primary" :disabled="busy" @click="run(() => meetingApi.adjournMeeting(meeting.id, ui.locale, closingNotes), true)">{{ tr('Finalizar y generar acta','Finish and generate minutes') }}</button></template>
      </section>
    </div>
  </section>
</template>

<script setup>
import MeetingCalendarReview from './MeetingCalendarReview.vue'
import MeetingOverview from './MeetingOverview.vue'
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import jsPDF from 'jspdf'
import 'jspdf-autotable'
import { meetingApi } from '../services/meetingApi'
import { superAdminApi } from '../services/superAdminApi'
import { useAuthStore } from '../stores/authStore'
import { useUiStore } from '../stores/uiStore'
const auth = useAuthStore(), ui = useUiStore(), route = useRoute()
const tr = (es,en) => ui.locale === 'es' ? es : en
const manager = computed(() => auth.can('meetings.manage'))
const canSubmit = computed(() => (auth.canEdit('meetings') || auth.canEdit('meeting_points')) && (manager.value || (auth.can('meeting_points.submit') && !!auth.user?.department_id)))
const meetings=ref([]), meeting=ref(null), selectedId=ref(''), points=ref([]), agenda=ref([]), report=ref([]), churches=ref([])
const loading=ref(true), busy=ref(false), error=ref(''), modalError=ref(''), tab=ref('meeting'), now=ref(Date.now())
const departmentFilter=ref(''), statusFilter=ref(''), reportSearch=ref('')
const newMeeting=ref(false), pointForm=ref(null), reviewForm=ref(null), decisionForm=ref(null), historyPoint=ref(null), finishConfirm=ref(false)
const closingNotes=ref('')
const create=ref({start:'',location:'',church_id:''}), opening=ref({prayer:'',remarks:''}), attendance=ref([]), summary=ref({public:false}), generalNote=ref('')
let timer, clock, alive=true, requestVersion=0, refreshing=false
const labels = computed(() => ({submitted:tr('Por revisar','To review'),accepted:tr('En agenda','On agenda'),rejected:tr('No admitido','Not admitted'),needs_update:tr('Actualizar solicitud','Updates requested'),approved:tr('Aceptado','Accepted'),denied:tr('Rechazado','Rejected'),postponed:tr('Próxima junta','Next meeting'),informative:tr('Informativo','Informative'),resubmitted:tr('Reenviado','Resubmitted'),active:tr('En discusión','In discussion'),carried_forward:tr('Trasladado de junta anterior','Carried from previous meeting')}))
const label = value => labels.value[value] || value
const date = value => value ? new Date(value).toLocaleString(ui.locale,{dateStyle:'medium',timeStyle:'short'}) : '—'
const state = m => m.end_at ? tr('Finalizada','Closed') : m.start_at ? tr('En vivo','Live') : m.agenda_closed_at || now.value >= new Date(m.submission_deadline).getTime() ? tr('Agenda cerrada','Agenda closed') : tr('Abierta','Open')
const accepting = computed(() => meeting.value && !meeting.value.start_at && !meeting.value.end_at && !meeting.value.agenda_closed_at && now.value < new Date(meeting.value.submission_deadline).getTime())
const live = computed(() => meeting.value?.start_at && !meeting.value?.end_at)
const undecided = computed(() => points.value.filter(p=>p.status==='accepted'&&!p.final_status).length)
const departments = computed(() => [...new Map(points.value.filter(p=>p.department).map(p=>[p.department.id,p.department])).values()])
const reviewStatuses=['submitted','accepted','needs_update','rejected']
const displayedAgenda = computed(() => manager.value ? points.value.filter(p=>(!departmentFilter.value || (departmentFilter.value==='clerk' ? !p.department_id : String(p.department_id)===departmentFilter.value)) && (!statusFilter.value || p.status===statusFilter.value)) : agenda.value)
const waitingPoints = computed(() => report.value.filter(p=>p.meeting?.end_at && ['postponed','needs_update'].includes(p.final_status) && !p.continuations?.length))
const previousMeeting = computed(() => meetings.value.filter(m => m.church_id === meeting.value?.church_id && m.id !== meeting.value?.id && m.end_at && new Date(m.end_at) <= new Date(meeting.value?.start_at)).sort((a,b)=>new Date(b.end_at)-new Date(a.end_at) || b.id-a.id)[0] || null)
const archive = computed(() => meetings.value.filter(m=>m.end_at))
const filteredReport = computed(() => report.value.filter(p=>[p.title,p.description,p.department?.name,label(p.final_status||p.status),p.final_note].join(' ').toLowerCase().includes(reportSearch.value.trim().toLowerCase())))
const modalTitle = computed(()=>newMeeting.value?tr('Abrir junta','Open meeting'):pointForm.value?tr('Punto de junta','Meeting point'):reviewForm.value?tr('Revisión de solicitud','Review request'):decisionForm.value?tr('Decisión de la junta','Meeting decision'):historyPoint.value?tr('Historial del punto','Point history'):tr('Finalizar junta','Finish meeting'))
const message = e => Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || tr('No se pudo completar la operación.','The operation could not be completed.')
function resetDrafts() {
  opening.value={prayer:meeting.value?.opening_prayer||'',remarks:meeting.value?.opening_remarks||''}
  attendance.value=(meeting.value?.attendance||[]).map(p=>({...p}))
  summary.value={public:!!meeting.value?.summary_public}
}
async function selectMeeting() {
  const version=++requestVersion, id=selectedId.value
  error.value=''; points.value=[];agenda.value=[];meeting.value=null
  departmentFilter.value='';statusFilter.value=''
  if(!id)return
  try {
    const [m,p,a]=await Promise.all([meetingApi.getMeeting(id),meetingApi.listMeetingPoints(id),manager.value?Promise.resolve([]):meetingApi.listMeetingPoints(id,{scope:'agenda'})])
    if(!alive||version!==requestVersion)return
    meeting.value=m;points.value=p;agenda.value=a;resetDrafts()
  } catch(e){if(alive&&version===requestVersion)error.value=message(e)}
}
async function refresh(silent=false) {
  if(refreshing)return
  refreshing=true
  const version=requestVersion, id=selectedId.value
  try {
    const [ms,rs]=await Promise.all([meetingApi.listMeetings(),meetingApi.report()])
    if(!alive||version!==requestVersion)return
    meetings.value=ms;report.value=rs
    if(!id && !silent){selectedId.value=String(ms.find(m=>String(m.id)===route.query.meeting)?.id || ms.find(m=>!m.end_at)?.id || ms[0]?.id || '');await selectMeeting()}
    else if(id){
      const [m,p,a]=await Promise.all([meetingApi.getMeeting(id),meetingApi.listMeetingPoints(id),manager.value?Promise.resolve([]):meetingApi.listMeetingPoints(id,{scope:'agenda'})])
      if(!alive||version!==requestVersion)return
      const justClosed=!meeting.value?.end_at&&m.end_at
      meeting.value=m;points.value=p;agenda.value=a
      if(!silent||justClosed)resetDrafts()
    }
  }catch(e){if(alive)error.value=message(e)}finally{refreshing=false;loading.value=false}
}
function closeModal(){if(busy.value)return;newMeeting.value=false;pointForm.value=null;reviewForm.value=null;decisionForm.value=null;historyPoint.value=null;finishConfirm.value=false;modalError.value=''}
async function run(action,close=false){if(busy.value)return;busy.value=true;error.value='';modalError.value='';try{await action();busy.value=false;if(close)closeModal();await refresh(true);ui.showToast(tr('Guardado.','Saved.'),'success');return true}catch(e){error.value=message(e);modalError.value=message(e);return false}finally{busy.value=false}}
function openPoint(p=null){modalError.value='';pointForm.value=p?{id:p.id,title:p.revision?.title||p.title,description:p.revision?.description||p.description}:{title:'',description:'',calendar_review:false,calendar_from:'',calendar_until:''}}
function reviewPoint(p){modalError.value='';reviewForm.value={id:p.id,title:p.title,status:p.status==='submitted'?'accepted':p.status,review_note:p.review_note||''}}
function decidePoint(p){modalError.value='';decisionForm.value={id:p.id,title:p.title,final_status:'approved',final_note:''}}
async function submitPoint(){const p=pointForm.value;await run(()=>p.id?meetingApi.updateMeetingPoint(p.id,{title:p.title,description:p.description}):meetingApi.createMeetingPoint(meeting.value.id,{title:p.title,description:p.description,calendar_review:!!p.calendar_review,...(p.calendar_review?{calendar_from:p.calendar_from,calendar_until:p.calendar_until}:{})}),true)}
async function submitReview(){const p=reviewForm.value;await run(()=>meetingApi.reviewMeetingPoint(p.id,{status:p.status,review_note:p.review_note}),true)}
async function submitDecision(){const p=decisionForm.value;await run(()=>meetingApi.finalizeMeetingPoint(p.id,{final_status:p.final_status,final_note:p.final_note}),true)}
async function createMeeting(){await run(async()=>{const start=new Date(create.value.start),offset=-start.getTimezoneOffset(),zone=`${offset>=0?'+':'-'}${String(Math.floor(Math.abs(offset)/60)).padStart(2,'0')}:${String(Math.abs(offset)%60).padStart(2,'0')}`;const m=await meetingApi.createMeeting({church_id:create.value.church_id||undefined,meeting_date:create.value.start.slice(0,10),planned_start_at:create.value.start+zone,location:create.value.location});selectedId.value=String(m.id);await selectMeeting();create.value={start:'',location:'',church_id:''}},true)}
async function saveOpening(){await run(()=>meetingApi.updateMeeting(meeting.value.id,{opening_prayer:opening.value.prayer,opening_remarks:opening.value.remarks,attendance:attendance.value}))}
async function saveSummary(){await run(()=>meetingApi.updateMeeting(meeting.value.id,{summary_public:summary.value.public}))}
async function saveNote(){if(await run(()=>meetingApi.addMeetingNote(meeting.value.id,{note:generalNote.value})))generalNote.value=''}
async function move(p,delta){const ids=points.value.map(p=>p.id),i=ids.indexOf(p.id),next=i+delta;if(next<0||next>=ids.length)return;[ids[i],ids[next]]=[ids[next],ids[i]];await run(()=>meetingApi.reorderMeetingPoints(meeting.value.id,ids))}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url)}
async function downloadSummary(m){try{downloadBlob(await meetingApi.downloadMeetingSummary(m.id,ui.locale),`meeting-minutes-${m.minutes_number}.pdf`)}catch(e){error.value=message(e)}}
function exportReport(type){
  const headers=[tr('Junta','Meeting'),tr('Departamento','Department'),tr('Punto','Point'),tr('Solicitud','Request'),tr('Revisión','Review'),tr('Decisión','Decision'),tr('Acuerdo','Decision note'),tr('Origen','Source')]
  const rows=filteredReport.value.map(p=>[date(p.meeting.planned_start_at),p.department?.name||tr('Secretaría','Clerk'),`#${p.id} · ${p.title}`,p.description,label(p.status),p.final_status?label(p.final_status):'',p.final_note||p.review_note||'',p.related_meeting_point_id||''])
  if(type==='csv'){const cell=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};downloadBlob(new Blob(['\uFEFF'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'meeting-points.csv')}
  else{const pdf=new jsPDF({orientation:'landscape'});pdf.setFontSize(14);pdf.text(tr('Historial de puntos de junta','Meeting point history'),14,16);pdf.autoTable({startY:24,head:[headers],body:rows,styles:{fontSize:8,overflow:'linebreak'},headStyles:{fillColor:[31,111,92]}});pdf.save('meeting-points.pdf')}
}
onMounted(async()=>{await refresh();if(auth.user?.role==='superadmin'){try{let page=1,result,all=[];do{result=await superAdminApi.listChurches({page:page++});all.push(...result.data)}while(result.next_page_url);if(alive)churches.value=all}catch(e){error.value=message(e)}}clock=setInterval(()=>now.value=Date.now(),1000);timer=setInterval(()=>{if(!busy.value&&!document.hidden)refresh(true)},15000)})
onUnmounted(()=>{alive=false;requestVersion++;clearInterval(timer);clearInterval(clock)})
</script>

