ng-left:7px;font-size:12px;color:#68766e}.status-pill{font-size:12px;padding:5px 9px;background:#edf3ef;border-radius:6px;color:#436351}.prewrap{white-space:pre-wrap;overflow-wrap:anywhere}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}label{display:block;font-size:12px}.form-control,.form-select{font-size:13px;margin-top:5px}.attendance-list{display:grid;gap:8px;margin:14px 0}.attendance-row{display:grid;grid-template-columns:1fr 160px auto;gap:10px;align-items:center}fieldset{border:0;padding:0;display:grid;gap:14px}.check-label input{width:16px;flex:0 0 16px;margin:0}.check-label{display:flex;align-items:center;gap:8px;margin:14px 0}.modal-panel form{margin-top:16px}.modal-panel{max-height:90vh;overflow:auto}.table{font-size:12px}.table th{font-weight:500;background:#f8faf9;color:#68766e}.table td,.table th{padding:12px}.history-entry{padding:12px 0;border-bottom:1px solid #edf0ed}@media(max-width:767px){.summary-grid,.form-grid{grid-template-columns:1fr}.attendance-row{grid-template-columns:1fr 110px auto}.surface{padding:14px}.toolbar .form-select{width:100%}}
